B.aKt=new A.a("\u0641\u0642\u0627\u0645 \u0633\u0639\u062f \u0645\u063a\u0636\u0628\u064b\u0627 \u0645\u0628\u0627\u062f\u0631\u064b\u0627 \u0645\u062e\u0648\u0641\u064b\u0627 \u0644\u0644\u0630\u064a \u0630\u0643\u0631 \u0644\u0647 \u0645\u0646 \u0623\u0645\u0631 \u0628\u0646\u064a \u062d\u0627\u0631\u062b\u0629\u060c \u0648\u0623\u062e\u0630 \u0627\u0644\u062d\u0631\u0628\u0629 \u0641\u064a \u064a\u062f\u0647 \u062b\u0645 \u0642\u0627\u0644: \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0623\u0631\u0627\u0643 \u0623\u063a\u0646\u064a\u062a \u0634\u064a\u0626\u064b\u0627\u060c \u062b\u0645 \u062e\u0631\u062c \u0625\u0644\u064a\u0647\u0645\u0627 \u0633\u0639\u062f \u0641\u0648\u062c\u062f\u0647\u0645\u0627 \u0645\u0637\u0645\u0626\u0646\u064a\u0646\u060c \u0641\u0639\u0631\u0641 \u0623\u0646 \u0623\u0633\u064a\u062f \u0625\u0646\u0645\u0627 \u0623\u0631\u0627\u062f \u0623\u0646 \u064a\u0633\u0645\u0639 \u0645\u0646\u0647\u0645\u0627\u060c \u0641\u0648\u0642\u0641 \u0645\u062a\u0634\u062a\u0645\u064b\u0627\u060c \u062b\u0645 \u0642\u0627\u0644 \u0644\u0623\u0633\u0639\u062f \u0628\u0646 \u0632\u0631\u0627\u0631\u0629: \u0648\u0627\u0644\u0644\u0647 \u064a\u0627 \u0623\u0628\u0627 \u0623\u0645\u0627\u0645\u0629 \u0644\u0648\u0644\u0627 \u0645\u0627 \u0628\u064a\u0646\u064a \u0648\u0628\u064a\u0646\u0643 \u0645\u0646 \u0627\u0644\u0642\u0631\u0627\u0628\u0629 \u0645\u0627 \u0631\u0645\u062a \u0647\u0630\u0627 \u0645\u0646\u064a\u060c \u0623\u062a\u063a\u0634\u0627\u0646\u0627 \u0641\u064a \u062f\u0627\u0631\u0646\u0627 \u0628\u0645\u0627 \u0646\u0643\u0631\u0647.",null)
B.aBj=new A.a("\u0648\u0643\u0627\u0646 \u0623\u0633\u0639\u062f \u0642\u062f \u0642\u0627\u0644 \u0644\u0645\u0635\u0639\u0628: \u0644\u0642\u062f \u062c\u0627\u0621 \u0648\u0627\u0644\u0644\u0647 \u0633\u064a\u062f \u0645\u0646 \u0648\u0631\u0627\u0626\u0647 \u0645\u0646 \u0642\u0648\u0645\u0647\u060c \u0625\u0646 \u064a\u062a\u0628\u0639\u0643 \u0644\u0627 \u064a\u062a\u062e\u0644\u0641 \u0645\u0646\u0647\u0645 \u0627\u062b\u0646\u0627\u0646\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0645\u0635\u0639\u0628: \u0623\u064e\u0648\u064e\u062a\u0642\u0639\u062f \u0641\u062a\u0633\u0645\u0639\u061f \u0641\u0625\u0646 \u0631\u0636\u064a\u062a \u0623\u0645\u0631\u064b\u0627 \u0648\u0631\u063a\u0628\u062a \u0641\u064a\u0647 \u0642\u0628\u0644\u062a\u0647\u060c \u0648\u0625\u0646 \u0643\u0631\u0647\u062a\u0647 \u0639\u0632\u0644\u0646\u0627 \u0639\u0646\u0643 \u0645\u0627 \u062a\u0643\u0631\u0647\u060c \u0641\u0642\u0627\u0644 \u0633\u0639\u062f: \u0623\u0646\u0635\u0641\u062a\u060c \u062b\u0645 \u0631\u0643\u0632 \u0627\u0644\u062d\u0631\u0628\u0629 \u0648\u062c\u0644\u0633 \u0641\u0639\u0631\u0636 \u0639\u0644\u064a\u0647 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0642\u0631\u0623 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0630\u0643\u0631 \u0645\u0648\u0633\u0649 \u0628\u0646 \u0639\u0642\u0628\u0629 \u0623\u0646\u0647 \u0642\u0631\u0623 \u0639\u0644\u064a\u0647 \u0623\u0648\u0644 \u0633\u0648\u0631\u0629 \u0627\u0644\u0632\u062e\u0631\u0641\u060c \u0642\u0627\u0644\u0627: \u0641\u0639\u0631\u0641\u0646\u0627 \u0648\u0627\u0644\u0644\u0647 \u0641\u064a \u0648\u062c\u0647\u0647 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 -\u0642\u0628\u0644 \u0623\u0646 \u064a\u062a\u0643\u0644\u0645- \u0641\u064a \u0625\u0634\u0631\u0627\u0642\u0647 \u0648\u062a\u0633\u0647\u0644\u0647.",null)
