B.avu=new A.a("\u0648\u0642\u0639 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0623\u0645\u064a\u0629 \u0627\u0644\u0636\u0645\u0631\u064a \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0623\u0633\u064a\u0631\u0627\u064b \u0641\u064a \u0628\u0626\u0631 \u0645\u0639\u0648\u0646\u0629 \u0648\u0644\u0645\u0627 \u0639\u0644\u0645 \u0639\u0627\u0645\u0631 \u0628\u0646 \u0627\u0644\u0637\u0641\u064a\u0644 \u0623\u0646\u0647 \u0645\u0646 \u0645\u0636\u0631 \u0623\u0637\u0644\u0642\u0647\u060c \u0648\u062c\u0632 \u0646\u0627\u0635\u064a\u062a\u0647 \u0648\u0623\u0639\u062a\u0642\u0647 \u0639\u0646 \u0631\u0642\u0628\u0629 \u0632\u0639\u0645 \u0623\u0646\u0647\u0627 \u0643\u0627\u0646\u062a \u0639\u0644\u0649 \u0623\u0645\u0647\u060c \u0641\u0644\u0645\u0627 \u062e\u0631\u062c \u0639\u0645\u0631\u0648 \u0642\u0627\u0635\u062f\u0627\u064b \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0646\u0632\u0644 \u0641\u064a \u0637\u0631\u064a\u0642\u0647 \u0641\u064a \u0638\u0644 \u0648\u0627\u0644\u062a\u0642\u0649 \u0628\u0631\u062c\u0644\u064a\u0646 \u0645\u0646 \u0628\u0646\u064a \u0639\u0627\u0645\u0631 \u0648\u0643\u0627\u0646 \u0645\u0639\u0647\u0645 \u0639\u0642\u062f \u0645\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0648\u062c\u0648\u0627\u0631 \u0644\u0645 \u064a\u0639\u0644\u0645 \u0628\u0647 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0623\u0645\u064a\u0629\u060c \u0648\u0642\u062f \u0633\u0623\u0644\u0647\u0645\u0627 \u062d\u064a\u0646 \u0646\u0632\u0644\u0627: \u0645\u0645\u0646 \u0623\u0646\u062a\u0645\u0627\u061f \u0641\u0642\u0627\u0644: \u0645\u0646 \u0628\u0646\u064a \u0639\u0627\u0645\u0631 \u0641\u0623\u0645\u0647\u0644\u0647\u0645\u0627 \u062d\u062a\u0649 \u0646\u0627\u0645\u0627\u060c \u0639\u062f\u0627 \u0639\u0644\u064a\u0647\u0645\u0627 \u0641\u0642\u062a\u0644\u0647\u0645\u0627 \u0648\u0647\u0648 \u064a\u0631\u0649 \u0623\u0646\u0647 \u0642\u062f \u0627\u0635\u0627\u0628 \u0628\u0647\u0645\u0627 \u062b\u064f\u0624\u0631\u0629 \u0645\u0646 \u0628\u0646\u064a \u0639\u0627\u0645\u0631\u060c \u0641\u064a\u0645\u0627 \u0623\u0635\u0627\u0628\u0648\u0627 \u0645\u0646 \u0623\u0635\u062d\u0627\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0644\u0645\u0627 \u0642\u062f\u0645 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0623\u0645\u064a\u0629 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0641\u0623\u062e\u0628\u0631\u0647 \u0627\u0644\u062e\u0628\u0631\u060c \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0644\u0642\u062f \u0642\u062a\u0644\u062a \u0642\u062a\u064a\u0644\u064a\u0646 \u0644\u0623\u062f\u064a\u0646\u0651\u064e\u0647\u0645\u0627 \u0648\u0647\u0630\u0627 \u0645\u0648\u0642\u0641 \u0631\u0641\u064a\u0639 \u0641\u0642\u062f \u0648\u064e\u0631\u064e\u0649 \ufdfa \u0630\u064a\u0646\u0643 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0627\u0644\u0639\u0627\u0645\u0631\u064a\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0642\u062a\u0644\u0647\u0645\u0627 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0623\u0645\u064a\u0629 \u0627\u0644\u0636\u0645\u0631\u064a \u0644\u0643\u0648\u0646\u0647\u0645\u0627 \u064a\u062d\u0645\u0644\u0627\u0646 \u0639\u0642\u062f\u0627\u064b \u0645\u0646\u0647 \ufdfa \u0648\u0644\u0645 \u064a\u0624\u0627\u062e\u0630\u0647\u0645\u0627 \u0628\u0645\u0627 \u0641\u0639\u0644 \u0628\u0639\u0636 \u0623\u0641\u0631\u0627\u062f \u0642\u0648\u0645\u0647\u0645\u0627\u060c \u0648\u0647\u0630\u0627 \u064a\u0645\u062b\u0644 \u0645\u0646\u062a\u0647\u0649 \u0627\u0644\u0642\u0645\u0629 \u0641\u064a \u0627\u0644\u0648\u0641\u0627\u0621 \u0628\u0627\u0644\u0639\u0647\u0648\u062f.",null)
B.atc=new A.a("\u0642\u062f \u0643\u0627\u0646 \u0628\u0625\u0645\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0646 \u064a\u0639\u062a\u0628\u0631 \u0639\u0645\u0644 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0623\u0645\u064a\u0629 \u062c\u0632\u0621\u0627\u064b \u0645\u0646 \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0645 \u0627\u0644\u0630\u064a \u064a\u0646\u0628\u063a\u064a \u0623\u0646 \u064a\u0648\u0627\u062c\u0647 \u0628\u0647 \u0627\u0644\u0645\u062c\u0631\u0645\u0648\u0646 \u0627\u0644\u0645\u0639\u062a\u062f\u0648\u0646\u060c \u0648\u0644\u0643\u0646 \u0645\u0627\u0630\u0646\u0628 \u0627\u0644\u0623\u0628\u0631\u064a\u0627\u0621 \u062d\u062a\u0649 \u064a\u0624\u062e\u0630\u0648\u0627 \u0628\u062c\u0631\u064a\u0631\u0629 \u0627\u0644\u0645\u0639\u062a\u062f\u064a\u0646 \u0645\u0646 \u0642\u0648\u0645\u0647\u0645\u060c \u0625\u0646 \u0627\u0644\u062a\u0648\u062c\u064a\u0647\u0627\u062a \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a\u0629 \u0627\u0644\u0631\u0641\u064a\u0639\u0629 \u062f\u0641\u0639\u062a \u0628\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0646\u0628\u064a\u0647\u0645 \ufdfa \u0625\u0644\u0649 \u0627\u0644\u0631\u0642\u064a \u0627\u0644\u0623\u062e\u0644\u0627\u0642\u064a \u0627\u0644\u0630\u064a \u0644\u0627\u0646\u0638\u064a\u0631 \u0644\u0647 \u0641\u064a \u062f\u0646\u064a\u0627 \u0627\u0644\u0646\u0627\u0633 .",null)
