B.atl=new A.a("\u0648\u0623\u0645\u0627 \u0643\u0633\u0631\u0649 \u0627\u0628\u0631\u0648\u064a\u0632 \u0641\u0644\u0645\u0627 \u0642\u0631\u0621 \u0639\u0644\u064a\u0647 \u0643\u062a\u0627\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa  \u0645\u0632\u0642\u0647\u060c \u0648\u0642\u0627\u0644: \u064a\u0643\u062a\u0628 \u0625\u0644\u064a\u0651\u064e \u0647\u0630\u0627 \u0648\u0647\u0648 \u0639\u0628\u062f\u064a\u061f \u0641\u0628\u0644\u063a \u0630\u0644\u0643 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0627\u0644: \u0645\u0632\u0642 \u0627\u0644\u0644\u0647 \u0645\u0644\u0643\u0647\u060c \u0648\u0623\u0645\u0631 \u0643\u0633\u0631\u0649 \u0628\u0627\u0630\u0627\u0646 \u0648\u0647\u0648 \u062d\u0627\u0643\u0645\u0647 \u0639\u0644\u0649 \u0627\u0644\u064a\u0645\u0646 \u0628\u0625\u062d\u0636\u0627\u0631\u0647 \u0641\u0623\u0631\u0633\u0644 \u0628\u0623\u0628\u0648\u064a\u0647 \u064a\u0642\u0648\u0644 \u0644\u0647: \u0625\u0646 \u0645\u0644\u0643 \u0627\u0644\u0645\u0644\u0648\u0643 \u0642\u062f \u0643\u062a\u0628 \u0627\u0644\u0649 \u0627\u0644\u0645\u0644\u0643 \u0628\u0627\u0630\u0627\u0646 \u064a\u0623\u0645\u0631\u0647 \u0623\u0646 \u064a\u0628\u0639\u062b \u0625\u0644\u064a\u0643 \u0645\u0646 \u064a\u0623\u062a\u064a\u0647 \u0628\u0643\u060c \u0648\u0642\u062f \u0628\u0639\u062b\u0646\u064a \u0625\u0644\u064a\u0643 \u0644\u062a\u0646\u0637\u0644\u0642 \u0645\u0639\u064a \u0641\u0623\u062e\u0628\u0631\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0623\u0646 \u0627\u0644\u0644\u0647 \u0633\u0644\u0637 \u0639\u0644\u0649 \u0643\u0633\u0631\u0649 \u0627\u0628\u0646\u0647 \u0634\u064a\u0631\u0648\u064a\u0647 \u0641\u0642\u062a\u0644\u0647\u060c \u0648\u0642\u062f \u062a\u062d\u0642\u0642 \u0645\u0627 \u0623\u0646\u0628\u0623 \u0628\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0628\u0643\u0644 \u062f\u0642\u0629\u060c \u0641\u0642\u062f \u0627\u0633\u062a\u0648\u0644\u0649 \u0639\u0644\u0649 \u0639\u0631\u0634\u0647 \u0627\u0628\u0646\u0647 \u0642\u0628\u0627\u0630 \u0627\u0644\u0645\u0644\u0642\u0628 \u0628\u0640 \u0634\u0631\u0648\u064a\u0647 \u0648\u0642\u062a\u0644 \u0643\u0633\u0631\u0649 \u0630\u0644\u064a\u0644\u0627\u064b \u0645\u0647\u0627\u0646\u0627\u064b \u0628\u0625\u064a\u0639\u0627\u0632 \u0645\u0646\u0647 \u0633\u0646\u0629 628\u0645 \u0648\u0642\u062f \u062a\u0645\u0632\u0642 \u0645\u0644\u0643\u0647 \u0628\u0639\u062f \u0648\u0641\u0627\u062a\u0647 \u0648\u0623\u0635\u0628\u062d \u0644\u0639\u0628\u0629 \u0641\u064a \u0623\u064a\u062f\u064a \u0623\u0628\u0646\u0627\u0621 \u0627\u0644\u0623\u0633\u0631\u0629 \u0627\u0644\u062d\u0627\u0643\u0645\u0629\u060c \u0641\u0644\u0645 \u064a\u0639\u0634 \u0634\u0631\u0648\u064a\u0647 \u0625\u0644\u0627 \u0633\u062a\u0629 \u0623\u0634\u0647\u0631\u060c \u0648\u062a\u0648\u0627\u0644\u0649 \u0639\u0644\u0649 \u0639\u0631\u0634\u0647 \u0645\u062f\u0629 \u0623\u0631\u0628\u0639 \u0633\u0646\u0648\u0627\u062a \u0639\u0634\u0631\u0629 \u0645\u0644\u0648\u0643\u060c \u0648\u0627\u0636\u0637\u0631\u0628 \u062d\u0628\u0644 \u0627\u0644\u062f\u0648\u0644\u0629 \u0627\u0644\u0649 \u0623\u0646 \u0627\u062c\u062a\u0645\u0639 \u0627\u0644\u0646\u0627\u0633 \u0639\u0644\u0649 \u064a\u0632\u062f\u062c\u0631\u062f \u0648\u0647\u0648 \u0622\u062e\u0631 \u0645\u0644\u0648\u0643 \u0628\u0646\u064a \u0633\u0627\u0633\u0627\u0646\u060c \u0648\u0647\u0648 \u0627\u0644\u0630\u064a \u0648\u0627\u062c\u0647 \u0627\u0644\u0632\u062d\u0641 \u0627\u0644\u0627\u0633\u0644\u0627\u0645\u064a \u0627\u0644\u0630\u064a \u0623\u062f\u0649 \u0627\u0644\u0649 \u0627\u0646\u0642\u0631\u0627\u0636 \u0627\u0644\u062f\u0648\u0644\u0629 \u0627\u0644\u0633\u0627\u0633\u0627\u0646\u064a\u0629 \u0627\u0644\u062a\u064a \u062f\u0627\u0645\u062a \u0648\u0627\u0632\u062f\u0647\u0631\u062a \u0623\u0643\u062b\u0631 \u0645\u0646 \u0623\u0631\u0628\u0639\u0629 \u0642\u0631\u0648\u0646 \u0627\u0646\u0642\u0631\u0627\u0636\u0627\u064b \u0643\u0644\u064a\u0627\u064b\u060c \u0648\u0643\u0627\u0646 \u0630\u0644\u0643 \u0641\u064a \u0633\u0646\u0629 637\u0645 \u0648\u0647\u0643\u0630\u0627 \u062a\u062d\u0642\u0642\u062a \u0647\u0630\u0647 \u0627\u0644\u0646\u0628\u0648\u0621\u0629 \u0641\u064a \u0638\u0631\u0641 \u062b\u0645\u0627\u0646\u064a \u0633\u0646\u064a\u0646.",null)
