B.aIE=new A.a("\u0648\u0642\u062f \u0642\u0627\u0644 \u0648\u0641\u062f \u0627\u0644\u064a\u0647\u0648\u062f \u0644\u0645\u0634\u0631\u0643\u064a \u0645\u0643\u0629 \u0623\u0646 \u062f\u064a\u0646\u0643\u0645 \u062e\u064a\u0631 \u0645\u0646 \u062f\u064a\u0646 \u0645\u062d\u0645\u062f \u0648\u0623\u0646\u062a\u0645 \u0623\u0648\u0644\u0649 \u0628\u0627\u0644\u062d\u0642 \u0645\u0646\u0647 \u0648\u0639\u0646 \u0630\u0644\u0643 \u064a\u0642\u0648\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 : \u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0646\u064e\u0635\u0650\u064a\u0628\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u0650 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u062c\u0650\u0628\u0652\u062a\u0650 \u0648\u064e\u0627\u0644\u0637\u0651\u064e\u0627\u063a\u064f\u0648\u062a\u0650 \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0647\u064e\u0624\u064f\u0644\u0627\u0621\u0650 \u0623\u064e\u0647\u0652\u062f\u064e\u0649 \u0645\u0650\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627 \u0633\u064e\u0628\u0650\u064a\u0644\u0627 \u0623\u064f\u0648\u0644\u064e\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0639\u064e\u0646\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0644\u0652\u0639\u064e\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u062c\u0650\u062f\u064e \u0644\u064e\u0647\u064f \u0646\u064e\u0635\u0650\u064a\u0631\u064b\u0627 - \u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0633\u0627\u0621",null)
B.aAr=new A.a("\u0648\u0642\u062f \u0623\u0628\u0631\u0645 \u0627\u0644\u0648\u0641\u062f \u0627\u0644\u064a\u0647\u0648\u062f\u064a \u0645\u0639 \u0632\u0639\u0645\u0627\u0621 \u0623\u0639\u0631\u0627\u0628 \u063a\u0637\u0641\u0627\u0646 \u0627\u062a\u0641\u0627\u0642\u064a\u0629 \u0627\u0644\u0627\u062a\u062d\u0627\u062f \u0627\u0644\u0639\u0631\u0628\u064a \u0627\u0644\u0648\u062b\u0646\u064a \u0627\u0644\u064a\u0647\u0648\u062f\u064a \u0627\u0644\u0639\u0633\u0643\u0631\u064a \u0636\u062f \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0648\u0643\u0627\u0646 \u0645\u0646 \u0628\u0646\u0648\u062f \u0627\u0644\u0627\u062a\u0641\u0627\u0642 : \u0623\u0646 \u062a\u0643\u0648\u0646 \u0642\u0648\u0629 \u063a\u0637\u0641\u0627\u0646 \u0641\u064a \u062c\u064a\u0634 \u0627\u0644\u0627\u062a\u062d\u0627\u062f \u0647\u0630\u0627 \u0633\u062a\u0629 \u0622\u0644\u0627\u0641 \u0645\u0642\u0627\u062a\u0644 \u060c \u0648\u0623\u0646 \u064a\u062f\u0641\u0639 \u0627\u0644\u064a\u0647\u0648\u062f \u0644\u0642\u0628\u0627\u0626\u0644 \u063a\u0637\u0641\u0627\u0646 \u0645\u0642\u0627\u0628\u0644 \u0630\u0644\u0643 \u0643\u0644 \u062a\u0645\u0631 \u062e\u064a\u0628\u0631 \u0644\u0633\u0646\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0648\u0644\u0642\u062f \u0627\u0633\u062a\u0637\u0627\u0639 \u0648\u0641\u062f \u0627\u0644\u064a\u0647\u0648\u062f \u0623\u0646 \u064a\u0631\u062c\u0639 \u0645\u0646 \u0631\u062d\u0644\u062a\u0647 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0648\u0645\u0639\u0647 \u0639\u0634\u0631\u0629 \u0622\u0644\u0627\u0641 \u0645\u0642\u0627\u062a\u0644\u060c \u0623\u0631\u0628\u0639\u0629 \u0622\u0644\u0627\u0641 \u0645\u0646 \u0642\u0631\u064a\u0634 \u0648\u0623\u062d\u0644\u0627\u0641\u0647\u0645\u0627\u060c \u0648\u0633\u062a\u0629 \u0622\u0644\u0627\u0641 \u0645\u0646 \u063a\u0637\u0641\u0627\u0646 \u0648\u0623\u062d\u0644\u0627\u0641\u0647\u0627\u060c \u0648\u0642\u062f \u0646\u0632\u0644\u062a \u062a\u0644\u0643 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0647\u0627\u0626\u0644\u0629 \u0628\u0627\u0644\u0642\u0631\u0628 \u0645\u0646 \u0627\u0644\u0645\u062f\u064a\u0646\u0629.",null)
