B.aCy=new A.a("\u0628\u0627\u0633\u0645\u0643 \u0627\u0644\u0644\u0647\u0645 - \u0647\u0630\u0627 \u0645\u0627\u0635\u0627\u0644\u062d \u0639\u0644\u064a\u0647 \u0645\u062d\u0645\u062f \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0633\u0647\u064a\u0644 \u0628\u0646 \u0639\u0645\u0631\u0648 - \u0648\u0627\u0635\u0637\u0644\u062d\u0627 \u0639\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u062d\u0631\u0628 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0633 \u0639\u0634\u0631 \u0633\u0646\u064a\u0646\u060c \u064a\u0623\u0645\u0646 \u0641\u064a\u0647\u0646 \u0627\u0644\u0646\u0627\u0633 \u0648\u064a\u0643\u0641 \u0628\u0639\u0636\u0647\u0645 \u0639\u0646 \u0628\u0639\u0636 - \u0639\u0644\u0649 \u0623\u0646\u0647 \u0645\u0646 \u0642\u062f\u0645 \u0645\u0643\u0629 \u0645\u0646 \u0623\u0635\u062d\u0627\u0628 \u0645\u062d\u0645\u062f \u062d\u0627\u062c\u0627\u064b \u0623\u0648 \u0645\u0639\u062a\u0645\u0631\u0627\u064b \u0623\u0648 \u064a\u0628\u062a\u063a\u064a \u0645\u0646 \u0641\u0636\u0644 \u0627\u0644\u0644\u0647 \u0641\u0647\u0648 \u0622\u0645\u0646 \u0639\u0644\u0649 \u062f\u0645\u0647 \u0648\u0645\u0627\u0644\u0647\u060c \u0648\u0645\u0646 \u0642\u062f\u0645 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0645\u0646 \u0642\u0631\u064a\u0634 \u0645\u062c\u062a\u0627\u0632\u0627\u064b \u0625\u0644\u0649 \u0645\u0635\u0631 \u0623\u0648 \u0625\u0644\u0649 \u0627\u0644\u0634\u0627\u0645\u060c \u064a\u0628\u062a\u063a\u064a \u0645\u0646 \u0641\u0636\u0644 \u0627\u0644\u0644\u0647 \u0641\u0647\u0648 \u0622\u0645\u0646 \u0639\u0644\u0649 \u062f\u0645\u0647 \u0648\u0645\u0627\u0644\u0647 - \u0639\u0644\u0649 \u0623\u0646\u0647 \u0645\u0646 \u0623\u062a\u0649 \u0645\u062d\u0645\u062f\u0627\u064b \u0645\u0646 \u0642\u0631\u064a\u0634 \u0628\u063a\u064a\u0631 \u0627\u0630\u0646 \u0648\u0644\u064a\u0647 \u0631\u062f\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0645\u0646 \u062c\u0627\u0621 \u0642\u0631\u064a\u0634\u0627\u064b \u0645\u0645\u0646 \u0645\u0639 \u0645\u062d\u0645\u062f \u0644\u0645 \u064a\u0631\u062f\u0648\u0647 \u0639\u0644\u064a\u0647 -\u0648\u0623\u0646 \u0628\u064a\u0646\u0646\u0627 \u0639\u064a\u0628\u0629 \u0645\u0643\u0641\u0648\u0641\u0629\u060c \u0648\u0623\u0646\u0647 \u0644\u0627\u0627\u0633\u0644\u0627\u0644 \u0648\u0644\u0627\u0627\u063a\u0644\u0627\u0644 -\u0648\u0623\u0646\u0647 \u0645\u0646 \u0623\u062d\u0628 \u0623\u0646 \u064a\u062f\u062e\u0644 \u0641\u064a \u0639\u0642\u062f \u0645\u062d\u0645\u062f \u0648\u0639\u0647\u062f\u0647 \u062f\u062e\u0644\u0647\u060c \u0648\u0645\u0646 \u0623\u062d\u0628 \u0623\u0646 \u064a\u062f\u062e\u0644 \u0641\u064a \u0639\u0642\u062f \u0642\u0631\u064a\u0634 \u0648\u0639\u0647\u062f\u0647\u0645 \u062f\u062e\u0644 \u0641\u064a\u0647 \u0641\u062a\u0648\u0627\u062b\u0628\u062a \u062e\u0632\u0627\u0639\u0629 \u0641\u0642\u0627\u0644\u0648\u0627: \u0646\u062d\u0646 \u0641\u064a \u0639\u0642\u062f \u0645\u062d\u0645\u062f \u0648\u0639\u0647\u062f\u0647\u060c \u0648\u062a\u0648\u0627\u062b\u0628\u062a \u0628\u0646\u0648 \u0628\u0643\u0631 \u0641\u0642\u0627\u0644\u0648\u0627: \u0646\u062d\u0646 \u0641\u064a \u0639\u0642\u062f \u0642\u0631\u064a\u0634 \u0648\u0639\u0647\u062f\u0647\u0645 - \u0648\u0623\u0646\u062a \u062a\u0631\u062c\u0639 \u0639\u0646\u0627 \u0639\u0627\u0645\u0643 \u0647\u0630\u0627\u060c \u0641\u0644\u0627 \u062a\u062f\u062e\u0644 \u0639\u0644\u064a\u0646\u0627 \u0645\u0643\u0629\u060c \u0648\u0623\u0646\u0647 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0639\u0627\u0645 \u0642\u0627\u0628\u0644 \u062e\u0631\u062c\u0646\u0627 \u0639\u0646\u0643 \u0641\u062f\u062e\u0644\u062a\u0647\u0627 \u0628\u0623\u0635\u062d\u0627\u0628\u0643\u060c \u0641\u0623\u0642\u0645\u062a \u0628\u0647\u0627 \u062b\u0644\u0627\u062b\u0627\u064b \u0645\u0639\u0643 \u0633\u0644\u0627\u062d \u0627\u0644\u0631\u0627\u0643\u0628\u060c \u0627\u0644\u0633\u064a\u0648\u0641 \u0641\u064a \u0627\u0644\u0642\u0631\u0628\u060c \u0648\u0644\u0627\u062a\u062f\u062e\u0644\u0647\u0627 \u0628\u063a\u064a\u0631\u0647\u0627 - \u0648\u0639\u0644\u0649 \u0623\u0646 \u0647\u0630\u0627 \u0627\u0644\u0647\u062f\u064a \u0645\u0627\u062c\u0626\u0646\u0627\u0647 \u0648\u0645\u062d\u0644\u0647 \u0641\u0644\u0627 \u062a\u0642\u062f\u0645\u0647 \u0639\u0644\u064a\u0646\u0627 \u0623\u0634\u0647\u062f \u0639\u0644\u0649 \u0627\u0644\u0635\u0644\u062d \u0631\u062c\u0627\u0644 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0631\u062c\u0627\u0644 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646:\u0641\u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646: \u0623\u0628\u0648 \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642\u060c \u0648\u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628\u060c \u0648\u0639\u0628\u062f\u0627\u0644\u0631\u062d\u0645\u0646 \u0628\u0646 \u0639\u0648\u0641\u060c \u0648\u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0633\u0647\u064a\u0644 \u0628\u0646 \u0639\u0645\u0631\u0648\u060c \u0648\u0633\u0639\u062f \u0628\u0646 \u0623\u0628\u064a \u0648\u0642\u0627\u0635\u060c \u0648\u0645\u062d\u0645\u062f \u0628\u0646 \u0633\u0644\u0645\u0629\u060c \u0648\u0639\u0644\u064a \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0643\u0627\u062a\u0628 \u0627\u0644\u0645\u0639\u0627\u0647\u062f\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u0623\u062c\u0645\u0639\u064a\u0646\u060c \u0648\u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0645\u0643\u0631\u0632 \u0628\u0646 \u062d\u0641\u0635 \u0648\u0633\u0647\u064a\u0644 \u0628\u0646 \u0639\u0645\u0631\u0648.",null)
