B.atn=new A.a("\u0643\u0627\u0646 \u0628\u0646\u0648 \u0627\u0644\u062d\u0627\u0631\u062b \u0628\u0646 \u0643\u0639\u0628 \u064a\u0633\u0643\u0646\u0648\u0646 \u0628\u0646\u062c\u0631\u0627\u0646 \u0648\u0644\u0645 \u064a\u0642\u0628\u0644 \u0645\u0646\u0647\u0645 \u0623\u062d\u062f \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u0628\u0639\u062b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0625\u0644\u064a\u0647\u0645 \u062e\u0627\u0644\u062f \u0628\u0646 \u0627\u0644\u0648\u0644\u064a\u062f \u0641\u064a \u0634\u0647\u0631 \u0631\u0628\u064a\u0639 \u0627\u0644\u0622\u062e\u0631 \u0623\u0648 \u062c\u0645\u0627\u062f\u064a \u0633\u0646\u0629 \u0639\u0634\u0631 \u0648\u0623\u0645\u0631\u0647 \u0623\u0646 \u064a\u062f\u0639\u0648\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0642\u0627\u062a\u0644\u0647\u0645 \u062b\u0644\u0627\u062b\u0627\u060c\u064b \u0641\u0625\u0646 \u0627\u0633\u062a\u062c\u0627\u0628\u0648\u0627 \u0642\u0628\u0644 \u0645\u0646\u0647\u0645 \u0648\u0625\u0646 \u0644\u0645 \u064a\u0641\u0639\u0644\u0648\u0627 \u0642\u0627\u062a\u0644\u0647\u0645\u060c \u0641\u062e\u0631\u062c \u062e\u0627\u0644\u062f \u062d\u062a\u0649 \u0642\u062f\u0645 \u0639\u0644\u064a\u0647\u0645 \u0641\u0628\u0639\u062b \u0627\u0644\u0631\u0643\u0628\u0627\u0646 \u0641\u064a \u0643\u0644 \u0648\u062c\u0647 \u064a\u062f\u0639\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0623\u0633\u0644\u0645 \u0627\u0644\u0646\u0627\u0633 \u0648\u062f\u062e\u0644\u0648\u0627 \u0641\u064a\u0645\u0627 \u062f\u0639\u0648\u0627 \u0625\u0644\u064a\u0647 \u0641\u0623\u0642\u0627\u0645 \u0641\u064a\u0647\u0645 \u062e\u0627\u0644\u062f \u064a\u0639\u0644\u0645\u0647\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0643\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0648\u0633\u0646\u0629 \u0646\u0628\u064a\u0647 \ufdfa \u0643\u0645\u0627 \u0623\u0645\u0631\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u062b\u0645 \u0643\u062a\u0628 \u062e\u0627\u0644\u062f \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u0639\u0644\u0645\u0647 \u0628\u0625\u0633\u0644\u0627\u0645\u0647\u0645 \u0648\u0623\u0646\u0647 \u0645\u0642\u064a\u0645 \u0641\u064a\u0647\u0645 \u062d\u062a\u0649 \u064a\u0643\u062a\u0628 \u0625\u0644\u064a\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u0641\u062c\u0627\u0621\u0647 \u0643\u062a\u0627\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u0623\u0645\u0631\u0647 \u0628\u0623\u0646 \u064a\u0642\u0628\u0644 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0648\u0645\u0639\u0647 \u0648\u0641\u062f \u0645\u0646\u0647\u0645 \u0641\u0641\u0639\u0644\u060c \u0641\u0644\u0645\u0627 \u0642\u062f\u0645\u0648\u0627 \u0623\u0645\u0631 \u0639\u0644\u064a\u0647\u0645 \u0642\u064a\u0633 \u0628\u0646 \u0627\u0644\u062d\u0635\u064a\u0646\u060c \u0648\u0628\u0639\u062b \u0625\u0644\u064a\u0647\u0645 \u0628\u0639\u062f \u0630\u0644\u0643 \u0639\u0645\u0631\u0648 \u0628\u0646 \u062d\u0632\u0645 \u0644\u064a\u0641\u0642\u0647\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u064a\u0646 \u0648\u064a\u0639\u0644\u0645\u0647\u0645 \u0627\u0644\u0633\u0646\u0629 \u0648\u0645\u0639\u0627\u0644\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.",null)
