B.aBm=new A.a("\u0643\u0627\u0646\u062a \u0627\u0644\u062d\u0631\u0648\u0628 \u062a\u0642\u0648\u0645 \u0628\u064a\u0646\u0647\u0645 \u0644\u0623\u062a\u0641\u0647 \u0627\u0644\u0623\u0633\u0628\u0627\u0628\u060c \u0641\u0647\u0645 \u0644\u0627 \u064a\u0628\u0627\u0644\u0648\u0646 \u0628\u0634\u0646 \u0627\u0644\u062d\u0631\u0648\u0628 \u0648\u0625\u0632\u0647\u0627\u0642 \u0627\u0644\u0623\u0631\u0648\u0627\u062d \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u062f\u0641\u0627\u0639 \u0639\u0646 \u0627\u0644\u0645\u062b\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0639\u0627\u0631\u0641\u0648\u0627 \u0639\u0644\u064a\u0647\u0627 \u0648\u0625\u0646 \u0643\u0627\u0646\u062a \u0644\u0627 \u062a\u0633\u062a\u062d\u0642 \u0627\u0644\u062a\u0642\u062f\u064a\u0631\u060c \u0648\u0642\u062f \u0631\u0648\u0649 \u0644\u0646\u0627 \u0627\u0644\u062a\u0627\u0631\u064a\u062e \u0633\u0644\u0633\u0644\u0629 \u0645\u0646 \u0623\u064a\u0627\u0645 \u0627\u0644\u0639\u0631\u0628 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0645\u0645\u0627 \u064a\u062f\u0644 \u0639\u0644\u0649 \u062a\u0645\u0643\u0646 \u0627\u0644\u0631\u0648\u062d \u0627\u0644\u062d\u0631\u0628\u064a\u0629 \u0645\u0646 \u0646\u0641\u0648\u0633 \u0627\u0644\u0639\u0631\u0628 \u0648\u063a\u0644\u0628\u062a\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0642\u0644 \u0648\u0627\u0644\u062a\u0641\u0643\u064a\u0631\u060c \u0641\u0645\u0646 \u062a\u0644\u0643 \u0627\u0644\u0623\u064a\u0627\u0645 \u0645\u062b\u0644\u0627 \u064a\u0648\u0645 \u0627\u0644\u0628\u0633\u0648\u0633\u060c \u0648\u0642\u062f \u0642\u0627\u0645\u062a \u0627\u0644\u062d\u0631\u0628 \u0641\u064a\u0647 \u0628\u064a\u0646 \u0628\u0643\u0631 \u0648\u062a\u063a\u0644\u0628 \u0628\u0633\u0628\u0628 \u0646\u0627\u0642\u0629 \u0644\u0644\u062c\u0631\u0645\u064a \u0648\u0647\u0648 \u062c\u0627\u0631 \u0644\u0644\u0628\u0633\u0648\u0633 \u0628\u0646\u062a \u0645\u0646\u0642\u0630 \u062e\u0627\u0644\u0629 \u062c\u0633\u0627\u0633 \u0628\u0646 \u0645\u0631\u0629\u060c \u0648\u0642\u062f \u0643\u0627\u0646 \u0643\u0644\u064a\u0628 \u0633\u064a\u062f \u062a\u063a\u0644\u0628 \u0642\u062f \u062d\u0645\u0649 \u0644\u0625\u0628\u0644\u0647 \u0645\u0643\u0627\u0646\u064b\u0627 \u062e\u0627\u0635\u064b\u0627 \u0628\u0647 \u0641\u0631\u0623\u0649 \u0641\u064a\u0647 \u0647\u0630\u0647 \u0627\u0644\u0646\u0627\u0642\u0629 \u0641\u0631\u0645\u0627\u0647\u0627 \u0641\u062c\u0632\u0639 \u0627\u0644\u062c\u0631\u0645\u064a \u0648\u062c\u0632\u0639\u062a \u0627\u0644\u0628\u0633\u0648\u0633\u060c \u0641\u0644\u0645\u0627 \u0631\u0623\u0649 \u0630\u0644\u0643 \u062c\u0633\u0627\u0633 \u062a\u062d\u064a\u0646 \u0627\u0644\u0641\u0631\u0635\u0629 \u0644\u0642\u062a\u0644 \u0643\u0644\u064a\u0628 \u0641\u0642\u062a\u0644\u0647 \u0641\u0642\u0627\u0645\u062a \u0627\u0644\u062d\u0631\u0648\u0628 \u0627\u0644\u0637\u0627\u062d\u0646\u0629 \u0628\u064a\u0646 \u0627\u0644\u0642\u0628\u064a\u0644\u062a\u064a\u0646 \u0644\u0645\u062f\u0629 \u0623\u0631\u0628\u0639\u064a\u0646 \u0633\u0646\u0629.",null)
B.aAS=new A.a("\u0648\u0643\u0630\u0644\u0643 \u0627\u0644\u062d\u0631\u0648\u0628 \u0627\u0644\u062a\u064a \u0642\u0627\u0645\u062a \u0628\u064a\u0646 \u0627\u0644\u0623\u0648\u0633 \u0648\u0627\u0644\u062e\u0632\u0631\u062c \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0648\u0647\u0645 \u0623\u0628\u0646\u0627\u0621 \u0639\u0645\u060c \u062d\u064a\u062b \u0625\u0646 \u0627\u0644\u0623\u0648\u0633 \u0648\u0627\u0644\u062e\u0632\u0631\u062c \u0623\u0628\u0646\u0627\u0621 \u062d\u0627\u0631\u062b\u0629 \u0628\u0646 \u062b\u0639\u0644\u0628\u0629 \u0627\u0644\u0623\u0632\u062f\u064a\u060c \u0648\u0627\u0633\u062a\u0645\u0631\u062a \u0627\u0644\u062d\u0631\u0648\u0628 \u0628\u064a\u0646\u0647\u0645 \u0648\u0643\u0627\u0646 \u0622\u062e\u0631 \u0623\u064a\u0627\u0645\u0647\u0645 (\u0628\u064f\u0639\u0627\u062b) \u0648\u0630\u0644\u0643 \u0623\u0646 \u062d\u0644\u0641\u0627\u0621 \u0627\u0644\u0623\u0648\u0633 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u062c\u062f\u062f\u0648\u0627 \u0639\u0647\u0648\u062f\u0647\u0645 \u0645\u0639\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0646\u0635\u0631\u0629\u060c \u0648\u0647\u0643\u0630\u0627 \u0643\u0627\u0646 \u0643\u062b\u064a\u0631 \u0645\u0646 \u062d\u0631\u0648\u0628 \u0627\u0644\u0623\u0648\u0633 \u0648\u0627\u0644\u062e\u0632\u0631\u062c \u064a\u0630\u0643\u064a\u0647\u0627 \u0627\u0644\u064a\u0647\u0648\u062f \u062d\u062a\u0649 \u064a\u0636\u0639\u0641\u0648\u0627 \u0627\u0644\u0642\u0628\u064a\u0644\u062a\u064a\u0646 \u0641\u062a\u0643\u0648\u0646 \u0644\u0647\u0645 \u0627\u0644\u0633\u064a\u0627\u062f\u0629 \u0627\u0644\u062f\u0627\u0626\u0645\u0629\u060c \u0648\u0627\u0633\u062a\u0639\u0627\u0646 \u0643\u0644 \u0641\u0631\u064a\u0642 \u0645\u0646\u0647\u0645 \u0628\u062d\u0644\u0641\u0627\u0626\u0647 \u0645\u0646 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u0645\u062c\u0627\u0648\u0631\u0629 \u0641\u0627\u0642\u062a\u062a\u0644\u0648\u0627 \u0642\u062a\u0627\u0644\u0627\u064b \u0634\u062f\u064a\u062f\u064b\u0627 \u0643\u0627\u0646\u062a \u0646\u0647\u0627\u064a\u062a\u0647 \u0644\u0635\u0627\u0644\u062d \u0627\u0644\u0623\u0648\u0633.",null)
B.aL5=new A.a("\u0648\u0643\u0627\u0646\u062a \u0628\u0639\u0636 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u062a\u0633\u0637\u0648 \u0648\u062a\u063a\u064a\u0631 \u0628\u063a\u064a\u0629 \u0646\u0647\u0628 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0648\u0633\u0628\u064a \u0627\u0644\u0623\u062d\u0631\u0627\u0631 \u0648\u0628\u064a\u0639\u0647\u0645\u060c \u0643\u0632\u064a\u062f \u0627\u0628\u0646 \u062d\u0627\u0631\u062b\u0629 \u0641\u0642\u062f \u0643\u0627\u0646 \u0639\u0631\u0628\u064a\u0651\u064b\u0627 \u062d\u0631\u064b\u0627\u060c \u0648\u0643\u0633\u0644\u0645\u0627\u0646 \u0627\u0644\u0641\u0627\u0631\u0633\u064a \u0641\u0642\u062f \u0643\u0627\u0646 \u0641\u0627\u0631\u0633\u064a\u0651\u064b\u0627 \u062d\u0631\u0651\u064b\u0627\u060c \u0648\u0642\u062f \u0642\u0636\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643 \u062d\u062a\u0649 \u0643\u0627\u0646\u062a \u062a\u0633\u064a\u0631 \u0627\u0644\u0645\u0631\u0623\u0629 \u0648\u0627\u0644\u0631\u062c\u0644 \u0645\u0646 \u0635\u0646\u0639\u0627\u0621 \u0625\u0644\u0649 \u062d\u0636\u0631\u0645\u0648\u062a \u0644\u0627 \u064a\u062e\u0627\u0641\u0627\u0646 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0630\u0626\u0628 \u0639\u0644\u0649 \u0623\u063a\u0646\u0627\u0645\u0647\u0645\u0627.",null)
