B.auu=new A.a("\u0625\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0645\u0641\u0631\u0648\u0636 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u0642\u0628\u0644 \u0627\u0644\u0645\u0648\u0644\u0649 \u0639\u0632\u0648\u062c\u0644 \u0623\u0646 \u064a\u0628\u0644\u063a\u0648\u0627 \u0631\u0633\u0627\u0644\u0627\u062a \u0627\u0644\u0644\u0647 \u0644\u0644\u0646\u0627\u0633 \u0643\u0627\u0641\u0629 \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \u0642\u064f\u0644\u0652 \u0647\u064e\u0630\u0650\u0647\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u064a \u0623\u064e\u062f\u0652\u0639\u064f\u0648 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0628\u064e\u0635\u0650\u064a\u0631\u064e\u0629\u064d \u0623\u064e\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0646\u0650\u064a \u0648\u064e\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e - \u0633\u0648\u0631\u0629 \u064a\u0648\u0633\u0641\u060c \u0648\u0623\u0639\u062f\u0627\u0621 \u0627\u0644\u0644\u0647 \u064a\u0635\u062f\u0648\u0646 \u0623\u0648\u0644\u064a\u0627\u0621\u0647 \u0639\u0646 \u062a\u0628\u0644\u064a\u063a \u0639\u0628\u0627\u062f\u0647 \u062f\u0639\u0648\u062a\u0647 \u0648\u0644\u0627\u064a\u062a\u0631\u0643\u0648\u0646 \u0644\u0647\u0645 \u0633\u0628\u064a\u0644\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u0646\u0627\u0633\u060c \u0643\u0645\u0627 \u0644\u0627\u064a\u0623\u0630\u0646\u0648\u0646 \u0644\u0644\u062f\u0639\u0627\u0629 \u0623\u0646 \u064a\u0633\u0645\u0639\u0648\u0627 \u0627\u0644\u062f\u0639\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0644\u0644\u0646\u0627\u0633\u060c \u0648\u064a\u0636\u0639\u0648\u0646 \u0627\u0644\u0639\u0631\u0627\u0642\u064a\u0644\u060c \u0648\u0627\u0644\u0639\u0648\u0627\u0626\u0642\u060c \u0648\u0627\u0644\u062d\u0648\u0627\u062c\u0632 \u0628\u064a\u0646 \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u062f\u0639\u0627\u062a\u0647\u0627 \u0648\u0627\u0644\u0646\u0627\u0633 \u0648\u0644\u0630\u0644\u0643 \u0623\u0648\u062c\u0628 \u0627\u0644\u0644\u0647 \u0639\u0632\u0648\u062c\u0644 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0642\u062a\u0627\u0644 \u0643\u0644 \u0645\u0646 \u064a\u0635\u062f \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.",null)
