B.az4=new A.a("\u0642\u0627\u0644 \u0639\u0628\u062f\u0627\u0644\u0631\u062d\u0645\u0646 \u0628\u0646 \u0639\u0648\u0641 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 : \u0628\u064a\u0646\u0645\u0627 \u0623\u0646\u0627 \u0648\u0627\u0642\u0641 \u0641\u064a \u0627\u0644\u0635\u0641 \u064a\u0648\u0645 \u0628\u062f\u0631 \u0646\u0638\u0631\u062a \u0639\u0646 \u064a\u0645\u064a\u0646\u064a \u0648\u0634\u0645\u0627\u0644\u064a \u0641\u0625\u0630\u0627 \u0623\u0646\u0627 \u0628\u064a\u0646 \u063a\u0644\u0627\u0645\u064a\u0646 \u0645\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u062d\u062f\u064a\u062b\u0629 \u0623\u0633\u0646\u0627\u0646\u0647\u0645\u0627 \u062a\u0645\u0646\u064a\u062a \u0644\u0648 \u0643\u0646\u062a \u0628\u064a\u0646 \u0623\u0636\u0644\u0639 \u0645\u0646\u0647\u0645\u0627\u060c \u0641\u063a\u0645\u0632\u0646\u064a \u0623\u062d\u062f\u0647\u0645\u0627 \u0641\u0642\u0627\u0644: \u064a\u0627\u0639\u0645 \u0647\u0644 \u062a\u0639\u0631\u0641 \u0623\u0628\u0627 \u062c\u0647\u0644\u061f \u0642\u0627\u0644:\u0642\u0644\u062a: \u0646\u0639\u0645 \u0648\u0645\u0627 \u062d\u0627\u062c\u062a\u0643 \u0625\u0644\u064a\u0647 \u064a\u0627 \u0627\u0628\u0646 \u0623\u062e\u064a\u061f \u0642\u0627\u0644: \u0623\u062e\u0628\u0631\u062a \u0623\u0646\u0647 \u064a\u0633\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0627\u0644\u0630\u064a \u0646\u0641\u0633\u064a \u0628\u064a\u062f\u0647 \u0644\u0626\u0646 \u0631\u0623\u064a\u062a\u0647 \u0644\u0627\u064a\u0641\u0627\u0631\u0642 \u0633\u0648\u0627\u062f\u064a \u0633\u0648\u0627\u062f\u0647 \u062d\u062a\u0649 \u064a\u0645\u0648\u062a \u0627\u0644\u0623\u0639\u062c\u0644 \u0645\u0646\u0627 \u0642\u0627\u0644: \u0641\u062a\u0639\u062c\u0628\u062a \u0644\u0630\u0644\u0643 \u0641\u063a\u0645\u0632\u0646\u064a \u0627\u0644\u0622\u062e\u0631 \u0641\u0642\u0627\u0644 \u0645\u062b\u0627\u0644\u0647\u0627.",null)
B.aJp=new A.a("\u0642\u0627\u0644: \u0641\u0644\u0645 \u0623\u0646\u0634\u0628 \u0623\u0646 \u0646\u0638\u0631\u062a \u0625\u0644\u0649 \u0623\u0628\u064a \u062c\u0647\u0644 \u064a\u0632\u0648\u0644 \u0641\u064a \u0627\u0644\u0646\u0627\u0633 \u0641\u0642\u0644\u062a: \u0623\u0644\u0627 \u062a\u0631\u064a\u0627\u0646\u061f \u0647\u0630\u0627 \u0635\u0627\u062d\u0628\u0643\u0645\u0627 \u0627\u0644\u0630\u064a \u062a\u0633\u0623\u0644\u0627\u0646 \u0639\u0646\u0647 \u0642\u0627\u0644: \u0641\u0627\u0628\u062a\u062f\u0631\u0627\u0647 \u0628\u0633\u064a\u0641\u064a\u0647\u0645\u0627 \u062d\u062a\u0649 \u0642\u062a\u0644\u0627\u0647\u060c \u062b\u0645 \u0627\u0646\u0635\u0631\u0641\u0627 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0623\u062e\u0628\u0631\u0627\u0647 \u0641\u0642\u0627\u0644: \u0623\u064a\u0643\u0645\u0627 \u0642\u062a\u0644\u0647\u061f \u0641\u0642\u0627\u0644 \u0643\u0644 \u0648\u0627\u062d\u062f \u0645\u0646\u0647\u0645\u0627: \u0623\u0646\u0627 \u0642\u062a\u0644\u062a\u0647 \u0641\u0642\u0627\u0644: \u0643\u0644\u0627\u0643\u0645\u0627 \u0642\u062a\u0644\u0647 \u0648\u0642\u0636\u0649 \u0628\u0633\u0644\u0628\u0647 \u0644\u0645\u0639\u0627\u0630 \u0628\u0646 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u062c\u0645\u0648\u062d \u0648\u0627\u0644\u0631\u062c\u0644\u0627\u0646 \u0645\u0639\u0627\u0630 \u0628\u0646 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u062c\u0645\u0648\u062d \u0648\u0645\u0639\u0627\u0630 \u0628\u0646 \u0639\u0641\u0631\u0627\u0621 \u0648\u0641\u064a \u062d\u062f\u064a\u062b \u0623\u0646\u0633 \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u0648\u0645 \u0628\u062f\u0631: \u0645\u0646 \u064a\u0646\u0638\u0631 \u0645\u0627\u0635\u0646\u0639 \u0623\u0628\u0648 \u062c\u0647\u0644\u061f \u0641\u0627\u0646\u0637\u0644\u0642 \u0627\u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0641\u0648\u062c\u062f\u0647 \u0642\u062f \u0636\u0631\u0628\u0627\u0647 \u0623\u0628\u0646\u0627\u0621 \u0639\u0641\u0631\u0627\u0621 \u062d\u062a\u0649 \u0628\u0631\u062f.",null)
