B.aYy=new A.a("\u0643\u0627\u0646\u062a \u0645\u0646 \u0646\u062a\u0627\u0626\u062c \u063a\u0632\u0648\u0629 \u0628\u062f\u0631 \u0623\u0646 \u0642\u0648\u064a\u062a \u0634\u0648\u0643\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0623\u0635\u0628\u062d\u0648\u0627 \u0645\u0631\u0647\u0648\u0628\u064a\u0646 \u0641\u064a \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0648\u0645\u0627 \u062c\u0627\u0648\u0631\u0647\u0627\u060c \u0648\u0623\u0635\u0628\u062d \u0645\u0646 \u064a\u0631\u064a\u062f \u0623\u0646 \u064a\u063a\u0632\u0648 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0623\u0648 \u064a\u0646\u0627\u0644 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0623\u0646 \u064a\u0641\u0643\u0631 \u0648\u064a\u0641\u0643\u0631 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0642\u062f\u0645 \u0639\u0644 \u0641\u0639\u0644\u062a\u0647 \u0648\u062a\u0639\u0632\u0632\u062a \u0645\u0643\u0627\u0646\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \u0641\u064a \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0648\u0627\u0631\u062a\u0641\u0639 \u0646\u062c\u0645 \u0627\u0644\u0627\u0633\u0644\u0627\u0645 \u0641\u064a\u0647\u0627 \u0648\u0644\u0645 \u064a\u0639\u062f \u0627\u0644\u0645\u062a\u0634\u0643\u0643\u0648\u0646 \u0628\u0627\u0644\u062f\u0639\u0648\u0629 \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0641\u064a \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u064a\u062a\u062c\u0631\u0624\u0648\u0646 \u0639\u0644\u0649 \u0625\u0638\u0647\u0627\u0631 \u0643\u0641\u0631\u0647\u0645 \u0648\u0639\u062f\u0627\u0648\u062a\u0647\u0645 \u0644\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0644\u0630\u0627 \u0638\u0647\u0631 \u0627\u0644\u0646\u0641\u0627\u0642 \u0648\u0627\u0644\u0645\u0643\u0631 \u0648\u0627\u0644\u062e\u062f\u0627\u0639 \u0641\u0623\u0639\u0644\u0646\u0648\u0627 \u0625\u0633\u0644\u0627\u0645\u0647\u0645 \u0638\u0627\u0647\u0631\u0627\u064b \u0623\u0645\u0627\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0623\u0635\u062d\u0627\u0628\u0647 \u0641\u062f\u062e\u0644\u0648\u0627 \u0641\u064a \u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0623\u0628\u0642\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0637\u0646\u0627\u064b.",null)
B.aU5=new A.a("\u0643\u0633\u0628 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0645\u0647\u0627\u0631\u0629 \u0639\u0633\u0643\u0631\u064a\u0629 \u0648\u0623\u0633\u0627\u0644\u064a\u0628 \u062c\u062f\u064a\u062f\u0629 \u0641\u064a \u0627\u0644\u062d\u0631\u0628 \u0648\u0634\u0647\u0631\u0629 \u0648\u0627\u0633\u0639\u0629 \u0641\u064a \u062f\u0627\u062e\u0644 \u0627\u0644\u062c\u0632\u064a\u0631\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u062e\u0627\u0631\u062c\u0647\u0627 \u0625\u0630 \u0623\u0635\u0628\u062d\u0648\u0627 \u0642\u0648\u0629 \u064a\u062d\u0633\u0628 \u0644\u0647\u0627 \u062d\u0633\u0627\u0628\u0647\u0627 \u0641\u064a \u0628\u0644\u0627\u062f \u0627\u0644\u0639\u0631\u0628 \u0648\u0627\u0646\u062a\u0639\u0634 \u062d\u0627\u0644 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0627\u0644\u0645\u0627\u062f\u064a \u0648\u0627\u0644\u0627\u0642\u062a\u0635\u0627\u062f\u064a \u0628\u0645\u0627 \u0623\u0641\u0627\u0621 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u063a\u0646\u0627\u0626\u0645 \u0628\u0639\u062f \u0628\u0624\u0633 \u0648\u0641\u0642\u0631 \u0634\u062f\u064a\u062f\u064a\u0646 \u062f\u0627\u0645\u0627 \u062a\u0633\u0639\u0629 \u0639\u0634\u0631 \u0634\u0647\u0631\u0627\u064b.",null)
