B.aHd=new A.a("\u0648\u0647\u0630\u0647 \u0627\u0628\u0646\u0629 \u0628\u0634\u064a\u0631 \u0628\u0646 \u0633\u0639\u062f \u062a\u0642\u0648\u0644: \u062f\u0639\u062a\u0646\u064a \u0623\u0645\u064a \u0639\u0645\u0631\u0629 \u0628\u0646\u062a \u0631\u0648\u0627\u062d\u0629 \u0641\u0623\u0639\u0637\u062a\u0646\u064a \u062d\u0641\u0646\u0629 \u0645\u0646 \u062a\u0645\u0631 \u0641\u064a \u062b\u0648\u0628\u064a \u062b\u0645 \u0642\u0627\u0644\u062a: \u0623\u064a\u0651 \u0628\u064f\u0646\u064a\u0651\u064e\u0629\u060c \u0625\u0630\u0647\u0628\u064a \u0625\u0644\u0649 \u0623\u0628\u064a\u0643 \u0648\u062e\u0627\u0644\u0643 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0631\u0648\u0627\u062d\u0629 \u0628\u063a\u062f\u0627\u0626\u0647\u0645\u0627\u060c \u0642\u0627\u0644\u062a: \u0641\u0623\u062e\u0630\u062a\u0647\u0627 \u0641\u0627\u0646\u0637\u0644\u0642\u062a \u0628\u0647\u0627 \u0641\u0645\u0631\u0631\u062a \u0628\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0623\u0646\u0627 \u0623\u0644\u062a\u0645\u0633 \u0623\u0628\u064a \u0648\u062e\u0627\u0644\u064a \u0641\u0642\u0627\u0644: \u062a\u0639\u0627\u0644\u064a \u064a\u0627\u0628\u0646\u064a\u0629 \u0645\u0627\u0647\u0630\u0627 \u0645\u0639\u0643\u061f \u0641\u0642\u0644\u062a: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0647\u0630\u0627 \u062a\u0645\u0631 \u0628\u0639\u062b\u062a\u0646\u064a \u0628\u0647 \u0623\u0645\u064a \u0625\u0644\u0649 \u0623\u0628\u064a \u0628\u0634\u064a\u0631 \u0628\u0646 \u0633\u0639\u062f\u060c \u0648\u062e\u0627\u0644\u064a \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0631\u0648\u0627\u062d\u0629 \u064a\u062a\u063a\u0630\u064a\u0627\u0646\u0647\u060c \u0642\u0627\u0644: \u0647\u0627\u062a\u064a\u0647 \u0642\u0627\u0644\u062a: \u0641\u0635\u0628\u0628\u062a\u0647 \u0641\u064a \u0643\u0641\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0645\u0627 \u0645\u0644\u0623\u062a\u0647\u0645\u0627\u060c \u062b\u0645 \u0623\u0645\u0631 \u0628\u062b\u0648\u0628 \u0641\u0628\u0633\u0637 \u0644\u0647 \u062b\u0645 \u062f\u0639\u0627 \u0628\u0627\u0644\u062a\u0645\u0631 \u0639\u0644\u064a\u0647 \u0641\u062a\u0628\u062f\u062f \u0641\u0648\u0642 \u0627\u0644\u062b\u0648\u0628 \u062b\u0645 \u0642\u0627\u0644 \u0644\u0625\u0646\u0633\u0627\u0646 \u0639\u0646\u062f\u0647: \u0627\u0635\u0631\u062e \u0641\u064a \u0623\u0647\u0644 \u0627\u0644\u062e\u0646\u062f\u0642 \u0623\u0646 \u0647\u0644\u0645\u0651 \u0625\u0644\u0649 \u0627\u0644\u063a\u0630\u0627\u0621\u060c \u0641\u0627\u062c\u062a\u0645\u0639 \u0623\u0647\u0644 \u0627\u0644\u062e\u0646\u062f\u0642 \u0639\u0644\u064a\u0647 \u0641\u062c\u0639\u0644\u0648\u0627 \u064a\u0623\u0643\u0644\u0648\u0646 \u0645\u0646\u0647 \u0648\u062c\u0639\u0644 \u064a\u0632\u064a\u062f \u062d\u062a\u0649 \u0635\u062f\u0631 \u0623\u0647\u0644 \u0627\u0644\u062e\u0646\u062f\u0642 \u0639\u0646\u0647\u060c \u0648\u0625\u0646\u0647 \u0644\u064a\u0633\u0642\u0637 \u0645\u0646 \u0623\u0637\u0631\u0627\u0641 \u0627\u0644\u062b\u0648\u0628.",null)
B.aNR=new A.a("\u0641\u0641\u064a \u0647\u0630\u064a\u0646 \u0627\u0644\u062e\u0628\u0631\u064a\u0646 \u0645\u0639\u062c\u0632\u0627\u062a \u062d\u0633\u064a\u0629 \u0638\u0627\u0647\u0631\u0629 \u0644\u0644\u0631\u0633\u0648\u0644 \ufdfa \u060c \u0643\u0645\u0627 \u064a\u0638\u0647\u0631 \u062f\u0648\u0631 \u0627\u0644\u0645\u0631\u0623\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u0629 \u0641\u064a \u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u062c\u0647\u0627\u062f\u0647\u0645\u060c \u0641\u0639\u0646\u062f\u0645\u0627 \u0627\u0634\u062a\u063a\u0644 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0628\u062d\u0641\u0631 \u0627\u0644\u062e\u0646\u062f\u0642 \u062a\u0631\u0643\u0648\u0627 \u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0648\u0628\u0639\u062f\u062a \u0639\u0646\u0647\u0645 \u0623\u0631\u0632\u0627\u0642\u0647\u0645\u060c \u0648\u0642\u0644\u0651 \u0639\u0646\u0647\u0645 \u0627\u0644\u0642\u0648\u062a \u0648\u0623\u0635\u0627\u0628 \u0627\u0644\u0646\u0627\u0633 \u062c\u0648\u0639 \u0648\u062d\u0631\u0645\u0627\u0646 \u062d\u062a\u0649 \u0643\u0627\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0645\u0639\u0647 \u064a\u0634\u062f\u0648\u0646 \u0639\u0644\u0649 \u0628\u0637\u0648\u0646\u0647\u0645 \u0627\u0644\u062d\u062c\u0627\u0631\u0629 \u0645\u0646 \u0634\u062f\u0629 \u0627\u0644\u062c\u0648\u0639\u060c \u0641\u0643\u0627\u0646\u062a \u0627\u0644\u0645\u0631\u0623\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u0629 \u062a\u0639\u064a\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0628\u0625\u0639\u062f\u0627\u062f \u0645\u0627\u0642\u062f\u0631\u062a \u0639\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u0637\u0639\u0627\u0645.",null)
